from fractions import Fraction as F
from math import factorial
def bn(n,k):
 r=F(1)
 for i in range(k):r*=F(n-i,i+1)
 return r
def c(g,q,a,s):
 h={-a-g+j:F(factorial(g))*bn(-a,g-j)*bn(a-4,j)*(-1)**j for j in range(g+1)};Q=q+2;z=-1 if s=='-' else 1;o={}
 for e,x in h.items():
  v=e+1+z*Q;o[e]=o.get(e,F())+x*v;o[e+1]=o.get(e+1,F())+x*(v-g)
 o={e:x for e,x in o.items() if x};return o if s=='-' else {e+Q:-x for e,x in o.items()}
def sub(v,w,z):
 for e,x in w.items():
  v[e]=v.get(e,F())-z*x
  if not v[e]:del v[e]
def hole(g,q,N=20):
 E=[];P=[];plus=[]
